preConditionHook:
// WFSafe_AvgTrueRange: MultiWalk's ROLLING accumulator, ported from
// AtrProfitTarget (the reference, with the measurements). Seeded with a full
// sum on the first calculated bar or when the length changes, and thereafter updated as
// TWO statements -- EL evaluates S[1] + in - out left to right, and folding it
// to S += in - out rounds differently (@OJ 2015-02-20).
// The local counter is atrLen, not atrLength: atrLength is this rule's INPUT.
if (atrLen != (int)atrLength) {
    atrSum = 0.0;
    for (int i = 0; i < (int)atrLength; ++i) {
        double hi = high[i] > close[i + 1] ? high[i] : close[i + 1];
        double lo = low[i] < close[i + 1] ? low[i] : close[i + 1];
        atrSum += hi - lo;
    }
    atrLen = (int)atrLength;
} else {
    const int out = (int)atrLength;
    double hiIn = high[0] > close[1] ? high[0] : close[1];
    double loIn = low[0] < close[1] ? low[0] : close[1];
    double hiOut = high[out] > close[out + 1] ? high[out] : close[out + 1];
    double loOut = low[out] < close[out + 1] ? low[out] : close[out + 1];
    atrSum += hiIn - loIn;
    atrSum -= hiOut - loOut;
}
atrVal = atrSum / (int)atrLength;
// The window is walked OLDEST FIRST -- idx counts down from windowBars - 1 to
// 0 -- so runHi is the running high of the bars up to and including idx and
// pbUp is the deepest retracement below it. Walking newest first would measure
// the distance to a FUTURE high, a different statistic. The EL twin runs the
// same loop with an explicit idx variable, since EasyLanguage has no
// descending for.
// Every comparison here is an ordinary EL relational, including the ones on
// computed price differences, so all of them go through el_gt/el_lt.
runHi = high[(int)windowBars - 1];
runLo = low[(int)windowBars - 1];
pbUp = 0.0;
pbDn = 0.0;
for (int k = 0; k < (int)windowBars; ++k) {
    int idx = (int)windowBars - 1 - k;
    if (el_gt(high[idx], runHi)) runHi = high[idx];
    if (el_gt(runHi - low[idx], pbUp)) pbUp = runHi - low[idx];
    if (el_lt(low[idx], runLo)) runLo = low[idx];
    if (el_gt(high[idx] - runLo, pbDn)) pbDn = high[idx] - runLo;
}
